  const bounded = Boolean(appliedFrom || appliedThrough);
  const shown = tasks.filter(task => (filter.value === 'All' || (filter.value === 'Completed') === task.completed) && (priorityFilter.value === 'All' || priorityFilter.value === task.priority) && (!bounded || (task.dueDate && (!appliedFrom || task.dueDate >= appliedFrom) && (!appliedThrough || task.dueDate <= appliedThrough))));

